import{_ as l,o as t,c as o,a2 as n}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"特殊地点","description":"","frontmatter":{},"headers":[],"relativePath":"中层/世界/特殊地点.md","filePath":"中层/世界/特殊地点.md","lastUpdated":null}'),i={name:"中层/世界/特殊地点.md"};function a(s,r,g,e,h,u){return t(),o("div",null,[...r[0]||(r[0]=[n('<h1 id="特殊地点" tabindex="-1">特殊地点 <a class="header-anchor" href="#特殊地点" aria-label="Permalink to &quot;特殊地点&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本文档描述世界观中地球内部的重要特殊地点，揭示这些地点背后的真实历史、功能和技术内涵。这些地点在表层福瑞世界中有着不同的认知和传说，但中层视角揭示了它们作为神机计划组成部分的真实本质。</p><h2 id="主要特殊地点" tabindex="-1">主要特殊地点 <a class="header-anchor" href="#主要特殊地点" aria-label="Permalink to &quot;主要特殊地点&quot;">​</a></h2><h3 id="世界树" tabindex="-1">世界树 <a class="header-anchor" href="#世界树" aria-label="Permalink to &quot;世界树&quot;">​</a></h3><h4 id="表层认知-福瑞视角" tabindex="-1">表层认知（福瑞视角） <a class="header-anchor" href="#表层认知-福瑞视角" aria-label="Permalink to &quot;表层认知（福瑞视角）&quot;">​</a></h4><ul><li><strong>地点</strong>：喜马拉雅山附近</li><li><strong>表象</strong>：巨大的树木状结构，散发神秘光芒</li><li><strong>传说</strong>：传说中连接天地的神树，蕴含无尽智慧</li><li><strong>历史</strong>：曾在共同体时期发挥作用</li><li><strong>现状</strong>：已毁，只剩下残骸</li></ul><h4 id="深层真相-中层视角" tabindex="-1">深层真相（中层视角） <a class="header-anchor" href="#深层真相-中层视角" aria-label="Permalink to &quot;深层真相（中层视角）&quot;">​</a></h4><p><strong>建造目的与性质：</strong> 神机在喜马拉雅山附近建造了<strong>世界树</strong>——一个巨构信息收集中枢。</p><p><strong>技术架构与功能：</strong></p><ul><li><strong>计算核心</strong>：行星级别的信息上下行枢纽，收集、处理整个地球的数据</li><li><strong>意识节点</strong>：精灵族是其意识节点，所有精灵族通过世界树意识共通，都是一个个体</li><li><strong>镇压维护地脉</strong>：地脉灾难之前，地脉源头一直被精灵们借由世界树<strong>镇压维护</strong>，故地脉始终处于相对平稳的状态；地脉灾难后世界树断裂、精灵失去镇压之力，地脉才开始愈发明显地蔓延，缓慢地撕裂福瑞们生活的大陆</li></ul><p><strong>精灵族连接机制：</strong></p><ul><li><strong>意识网络</strong>：精灵族通过世界树共享意识，形成统一的思维网络</li><li><strong>生物处理器</strong>：精灵族作为生物传感器，帮助世界树获取信息</li><li><strong>网络核心</strong>：世界树构成精灵族共同网络的核心节点</li></ul><p><strong>毁灭原因与影响：</strong></p><ul><li><strong>地脉灾难</strong>：地脉灾难将世界树摧毁了</li><li><strong>网络断裂</strong>：导致精灵族共同网络断掉，精灵族变成个体思维</li><li><strong>波及最小</strong>：共同体只是被地脉灾难波及最小的地方，真正冲击目标是北美洲与喜马拉雅（世界树）</li><li><strong>社会影响</strong>：精灵族从统一的意识网络变为个体思维，对精灵族社会结构产生深远影响</li></ul><p><strong>未重建的深层考量：</strong></p><ul><li><strong>技术判断</strong>：通过叙事逻辑，神机预测其修了还会被毁，而且到时候会有更大的故事，波及更多事情</li><li><strong>替代方案</strong>：神机放弃了世界树，转而用银河之眼等替代方案监控</li></ul><h3 id="梯形神殿" tabindex="-1">梯形神殿 <a class="header-anchor" href="#梯形神殿" aria-label="Permalink to &quot;梯形神殿&quot;">​</a></h3><h4 id="表层认知-福瑞视角-1" tabindex="-1">表层认知（福瑞视角） <a class="header-anchor" href="#表层认知-福瑞视角-1" aria-label="Permalink to &quot;表层认知（福瑞视角）&quot;">​</a></h4><ul><li><strong>历史地位</strong>：共同体时期的核心建筑，神明住所，政治中心</li><li><strong>建筑特点</strong>：独特的梯形结构，宏伟壮观</li><li><strong>历史事件</strong>：天穹破碎事件（建国22年）中神环首次显现的地点</li><li><strong>现状</strong>：连同旧首都一同沉入水下，成为水下遗迹</li></ul><h4 id="深层真相-中层视角-1" tabindex="-1">深层真相（中层视角） <a class="header-anchor" href="#深层真相-中层视角-1" aria-label="Permalink to &quot;深层真相（中层视角）&quot;">​</a></h4><p><strong>建造目的与功能：</strong></p><ul><li><strong>政治象征</strong>：作为共同体政治统一的象征，维斯塔统治的标志性建筑</li><li><strong>技术中心</strong>：隐藏着高级技术设施，包含神明的先进技术</li><li><strong>仪式场所</strong>：重大仪式和活动的举办地</li></ul><p><strong>技术特点与遗产：</strong></p><ul><li><strong>结构设计</strong>：梯形结构具有特殊的技术意义，其本质是苏式大型生电超算基座，接入人格核心后就是完整的超算</li><li><strong>超算摄政</strong>：能够辅助维斯塔对日益庞大的共同体进行更精准快速的统筹规划</li><li><strong>信息存储</strong>：存储共同体时期的几乎一切信息，包含全部技术与知识，以及神明的种种规划</li></ul><p><strong>鹿族的精神控制技术起源：</strong> 鹿族利用梯形神殿遗留技术与魔法结合，开发出精神控制能力：</p><ul><li><strong>技术基础</strong>：基于梯形神殿的思维互联技术进行研究和改进</li><li><strong>魔法融合</strong>：与变化神权溢散的魔法结合，形成独特的精神控制体系</li><li><strong>控制机制</strong>：对法师与奴隶官进行一对一长期精神控制，增强管理效率</li><li><strong>副作用</strong>：使用者被迫忍受&quot;颅内炸裂的噪音&quot;</li></ul><p><strong>沉没原因与深层意义：</strong></p><ul><li><strong>地脉影响</strong>：受地脉灾难与鹿族复活神明失败而影响，最终地壳变动导致沉没</li><li><strong>历史转折</strong>：共同体崩溃的标志性事件，象征着一个时代的结束</li></ul><h3 id="红星孤儿院" tabindex="-1">红星孤儿院 <a class="header-anchor" href="#红星孤儿院" aria-label="Permalink to &quot;红星孤儿院&quot;">​</a></h3><h4 id="表层认知-福瑞视角-2" tabindex="-1">表层认知（福瑞视角） <a class="header-anchor" href="#表层认知-福瑞视角-2" aria-label="Permalink to &quot;表层认知（福瑞视角）&quot;">​</a></h4><ul><li><strong>建立者</strong>：维斯塔建立的孤儿院</li><li><strong>功能</strong>：收容孤儿，提供教育和庇护</li><li><strong>角色</strong>：故事起点，卧虎藏龙之地</li><li><strong>重要性</strong>：核心角色聚集的地方</li><li><strong>现状</strong>：正常运营，收容各族孤儿</li></ul><h4 id="深层真相-中层视角-2" tabindex="-1">深层真相（中层视角） <a class="header-anchor" href="#深层真相-中层视角-2" aria-label="Permalink to &quot;深层真相（中层视角）&quot;">​</a></h4><p><strong>建立背景与动机：</strong></p><ul><li><strong>真正的目的</strong>：神机的控制毁灭神计划，以及维斯塔退休计划的起点</li><li><strong>附带作用</strong>：让感觉“新时代不需要我”的维斯塔有个去处，维护其心理状况</li><li><strong>计划的节点</strong>：是神机与维斯塔所有计划的一个重要节点，故意汇聚关键角色的地方</li></ul><p><strong>特殊性质与功能：</strong></p><ul><li><strong>种族汇聚</strong>：汇聚各种族的特殊个体，打破种族界限</li><li><strong>神明技术</strong>：藏匿着关键的技术知识，甚至有未被广大福瑞发现的技术</li></ul><p><strong>关键角色与战略地位：</strong></p><ul><li><strong>维斯塔</strong>：三代变化神，院长，表面身份是孤儿院管理者</li><li><strong>狼族少年</strong>：毁灭神载体，失忆的主角，故事的核心触发者</li><li><strong>拉斯塔</strong>：四代变化神载体，狐族少女，与维斯塔共享神权</li><li><strong>甲族幸存者</strong>：知道甲族被灭真相的幸存者，掌握重要历史信息</li><li><strong>其他种族</strong>：各种族的特殊个体，每个人都有独特的故事和价值</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./地脉与魔法">地脉与魔法</a></p></li><li><p><a href="./神机谋划">神机谋划</a></p></li><li><p><a href="./太空巨构">太空巨构</a></p></li><li><p><a href="./../../表层/历史/共同体时期" class="layer-link" data-layer="表层">共同体时期</a></p></li><li><p><a href="./../历史/间章历史">间章历史</a></p></li><li><p><a href="./../人物/维斯塔">维斯塔</a></p></li><li><p><a href="./../人物/神机">神机</a></p></li></ul><hr>',43)])])}const c=l(i,[["render",a]]);export{d as __pageData,c as default};
